{"command":"python3 - <<'PY'
import subprocess, os, glob, tempfile
WS=os.getcwd(); EXE=os.path.join(WS,"executable")
def R(args, cwd=None):
    return subprocess.run([EXE]+args, cwd=cwd or WS, capture_output=True, text=True)
# Check help when COLUMNS / tty width changes; clap wraps at terminal width?
import pty, fcntl, termios, struct, select
def run_pty(args, cols=80):
    pid, fd = pty.fork()
    if pid==0:
        os.chdir(WS); os.execve(EXE, [EXE]+args, dict(os.environ))
    else:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", 40, cols, 0,0))
        out=b""
        while True:
            try: r,_,_=select.select([fd],[],[],0.5)
            except: break
            if not r: break
            try: d=os.read(fd,65536)
            except: break
            if not d: break
            out+=d
        os.waitpid(pid,0); return out.decode(errors='surrogateescape')
for cols in [40,80,120,200]:
    out=run_pty(["-h"], cols=cols)
    print(f"cols {cols} lines:")
    for l in out.splitlines()[:15]: print(repr(l))
    print("...")

# Env COLUMNS for non-tty
for cols in ["40","200"]:
    env=dict(os.environ); env["COLUMNS"]=cols
    r=subprocess.run([EXE,"-h"], cwd=WS, capture_output=True, text=True, env=env)
    print("COLUMNS env",cols, r.stdout.splitlines()[8])
PY
"}

