import pty, os, fcntl, termios, struct, select
WS="/workspace"; EXE=os.path.join(WS,"executable")
def run_pty(args, cols=80, rows=50, env_extra=None, cwd=None):
    pid, fd = pty.fork()
    if pid==0:
        env=dict(os.environ)
        if env_extra: env.update(env_extra)
        os.chdir(cwd or WS); os.execve(EXE, [EXE]+args, env)
    else:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0,0))
        out=b""
        while True:
            try: r,_,_=select.select([fd],[],[],1.0)
            except: break
            if not r: break
            try: data=os.read(fd, 65536)
            except OSError: break
            if not data: break
            out+=data
        os.waitpid(pid,0)
        return out.decode(errors='surrogateescape')
PY
