WS="/workspace"; EXE=WS+"/executable"
cands=[]
for root in ["/var","/etc","/usr","/run","/sys","/proc"]:
    for dp,dn,fn in os.walk(root):
        for n in fn:
            p=os.path.join(dp,n)
            try: st=os.lstat(p)
            except: continue
            if st.st_uid==101 or st.st_gid==101:
                cands.append(p)
        if len(cands)>3: break
    if len(cands)>3: break
print(cands)
for p in cands[:3]:
    r=subprocess.run([EXE,p,"-d=user","-d=uid","-d=group","-d=gid","-i=false"],cwd=WS,capture_output=True,text=True)
    print(p, repr(r.stdout))
