// ---------- user / group lookup ----------

fn user_cache() -> &'static Mutex<HashMap<u32, Option<String>>> {
    static CACHE: OnceLock<Mutex<HashMap<u32, Option<String>>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}
fn group_cache() -> &'static Mutex<HashMap<u32, Option<String>>> {
    static CACHE: OnceLock<Mutex<HashMap<u32, Option<String>>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

fn lookup_user(uid: u32) -> Option<String> {
    if let Some(v) = user_cache().lock().unwrap().get(&uid).cloned() {
        return v;
    }
    let name = unsafe {
        let mut pwd: libc::passwd = std::mem::zeroed();
        let mut buf = vec![0_i8; 4096];
        let mut result: *mut libc::passwd = std::ptr::null_mut();
        let rc = libc::getpwuid_r(
            uid,
            &mut pwd,
            buf.as_mut_ptr(),
            buf.len(),
            &mut result,
        );
        if rc == 0 && !result.is_null() && !pwd.pw_name.is_null() {
            Some(CStr::from_ptr(pwd.pw_name).to_string_lossy().into_owned())
        } else {
            None
        }
    };
    user_cache().lock().unwrap().insert(uid, name.clone());
    name
}

fn lookup_group(gid: u32) -> Option<String> {
    if let Some(v) = group_cache().lock().unwrap().get(&gid).cloned() {
        return v;
    }
    let name = unsafe {
        let mut grp: libc::group = std::mem::zeroed();
        let mut buf = vec![0_i8; 4096];
        let mut result: *mut libc::group = std::ptr::null_mut();
        let rc = libc::getgrgid_r(
            gid,
            &mut grp,
            buf.as_mut_ptr(),
            buf.len(),
            &mut result,
        );
        if rc == 0 && !result.is_null() && !grp.gr_name.is_null() {
            Some(CStr::from_ptr(grp.gr_name).to_string_lossy().into_owned())
        } else {
            None
        }
    };
    group_cache().lock().unwrap().insert(gid, name.clone());
    name
}

// ---------- Node ----------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum NodeType {
    Dir,
    Symlink,
    Fifo,
    Socket,
    BlockDevice,
    CharDevice,
    File,
}

impl NodeType {
    fn from_metadata(md: &Metadata) -> Self {
        let ft = md.file_type();
        if ft.is_dir() {
            NodeType::Dir
        } else if ft.is_symlink() {
            NodeType::Symlink
        } else if ft.is_fifo() {
            NodeType::Fifo
        } else if ft.is_socket() {
            NodeType::Socket
        } else if ft.is_block_device() {
            NodeType::BlockDevice
        } else if ft.is_char_device() {
            NodeType::CharDevice
        } else {
            NodeType::File
        }
    }
    fn type_char(&self) -> char {
        match self {
            NodeType::Dir => 'd',
            NodeType::File => 'f',
            NodeType::Symlink => 'l',
            NodeType::Fifo => 'p',
            NodeType::Socket => 's',
            NodeType::BlockDevice => 'b',
            NodeType::CharDevice => 'c',
        }
    }
    fn suffix(&self) -> &'static str {
        match self {
            NodeType::Dir => "/",
            NodeType::Symlink => "@",
            NodeType::Fifo => "|",
            NodeType::Socket => "=",
            _ => "",
        }
    }
    fn filter(&self) -> TypeFilter {
        match self {
            NodeType::Dir => TypeFilter::Dir,
            NodeType::Symlink => TypeFilter::Symlink,
            NodeType::Fifo => TypeFilter::Fifo,
            NodeType::Socket => TypeFilter::Socket,
            NodeType::BlockDevice => TypeFilter::BlockDevice,
            NodeType::CharDevice => TypeFilter::CharDevice,
            NodeType::File => TypeFilter::File,
        }
    }
}

pub struct Node {
    path: PathBuf,
    display_name: String,
    pub base_name: String,
    explicit: bool,
    metadata: Metadata,
    node_type: NodeType,
    user: Option<String>,
    group: Option<String>,
}

impl Node {
    fn new(path: PathBuf, display_name: String, explicit: bool, metadata: Metadata) -> Self {
        let base_name = if explicit {
            Path::new(&path)
                .file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| display_name.clone())
        } else {
            display_name.clone()
        };
        let node_type = NodeType::from_metadata(&metadata);
        let user = lookup_user(metadata.uid());
        let group = lookup_group(metadata.gid());
        Node {
            path,
            display_name,
            base_name,
            explicit,
            metadata,
            node_type,
            user,
            group,
        }
    }

    pub fn dev_value(&self) -> u64 {
        self.metadata.dev()
    }
    pub fn ino_value(&self) -> u64 {
        self.metadata.ino()
    }
    pub fn nlink_value(&self) -> u64 {
        self.metadata.nlink()
    }
    pub fn type_rank(&self) -> u8 {
        match self.node_type {
            NodeType::Dir => 0,
            NodeType::Symlink => 1,
            NodeType::Fifo => 2,
            NodeType::Socket => 3,
            NodeType::BlockDevice => 4,
            NodeType::CharDevice => 5,
            NodeType::File => 6,
        }
    }
    pub fn cat_rank(&self) -> u8 {
        if self.node_type == NodeType::Dir {
            0
        } else {
            1
        }
    }
    pub fn user_value(&self) -> &Option<String> {
        &self.user
    }
    pub fn uid_value(&self) -> u32 {
        self.metadata.uid()
    }
    pub fn group_value(&self) -> &Option<String> {
        &self.group
    }
    pub fn gid_value(&self) -> u32 {
        self.metadata.gid()
    }
    pub fn size_value(&self) -> Option<u64> {
        if self.node_type == NodeType::Dir {
            None
        } else {
            Some(self.metadata.len())
        }
    }
    pub fn blocks_value(&self) -> Option<u64> {
        if self.node_type == NodeType::Dir {
            None
        } else {
            Some(self.metadata.blocks())
        }
    }
    fn time_key(t: SystemTime) -> (i64, u32) {
        match t.duration_since(UNIX_EPOCH) {
            Ok(d) => (d.as_secs() as i64, d.subsec_nanos()),
            Err(e) => {
                let d = e.duration();
                if d.subsec_nanos() == 0 {
                    (-(d.as_secs() as i64), 0)
                } else {
                    (-(d.as_secs() as i64) - 1, 1_000_000_000 - d.subsec_nanos())
                }
            }
        }
    }
    pub fn btime_key(&self) -> Option<(i64, u32)> {
        self.metadata.created().ok().map(Self::time_key)
    }
    pub fn ctime_key(&self) -> Option<(i64, u32)> {
        Some((self.metadata.ctime(), self.metadata.ctime_nsec() as u32))
    }
    pub fn mtime_key(&self) -> Option<(i64, u32)> {
        self.metadata.modified().ok().map(Self::time_key)
    }
    pub fn atime_key(&self) -> Option<(i64, u32)> {
        self.metadata.accessed().ok().map(Self::time_key)
    }
    pub fn cname(&self) -> String {
        self.base_name
            .trim_start_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase()
    }
    pub fn ext_value(&self) -> Option<OsString> {
        Path::new(&self.base_name).extension().map(|s| s.to_os_string())
    }

    fn importance(&self) -> i8 {
        let name = &self.base_name;
        if name == ".git" || name == ".DS_Store" {
            -1
        } else if name.starts_with('.') {
            0
        } else if name == "Cargo.lock" {
            0
        } else if name == "src" {
            2
        } else if is_word_prefix(name, "README") {
            3
        } else {
            1
        }
    }

    fn imp_diff(&self, cutoff: i8) -> i8 {
        self.importance().wrapping_sub(cutoff)
    }

    fn icon(&self) -> Option<&'static str> {
        icon_for(&self.base_name, self.node_type)
    }
}

fn is_word_prefix(name: &str, prefix: &str) -> bool {
    if name == prefix {
        return true;
    }
    if let Some(rest) = name.strip_prefix(prefix) {
        if let Some(c) = rest.chars().next() {
            return !(c.is_alphanumeric() || c == '_');
        }
    }
    false
}

fn icon_for(name: &str, node_type: NodeType) -> Option<&'static str> {
    // Exact / special name rules.
    let special: Option<&'static str> = if name == ".git" || name == ".gitignore" {
        Some("\u{f02a2}")
    } else if name == ".github" {
        Some("\u{f0408}")
    } else if name == ".DS_Store" {
        Some("\u{f179}")
    } else if is_word_prefix(name, ".env") {
        Some("\u{e22f}")
    } else if name.contains("Dockerfile") {
        Some("\u{f4b7}")
    } else if name.contains("docker-compose") && name.ends_with(".yml") {
        Some("\u{f4b7}")
    } else if name == "Cargo.toml" {
        Some("\u{f0487}")
    } else if name == "Cargo.lock" {
        Some("\u{f0456}")
    } else if name == "Makefile" || name == "justfile" {
        Some("\u{f070e}")
    } else if is_word_prefix(name, "README") {
        Some("\u{f02d}")
    } else if is_word_prefix(name, "LICENSE") {
        Some("\u{f0495}")
    } else if name == "rustfmt.toml" {
        Some("\u{f00e2}")
    } else if name == "src" {
        Some("\u{f40d}")
    } else {
        None
    };
    if let Some(s) = special {
        return Some(s);
    }
    // Extension rules: suffix after the last dot (if any).
    if let Some(pos) = name.rfind('.') {
        let ext = &name[pos + 1..];
        let by_ext: Option<&'static str> = match ext {
            "txt" | "rtf" => Some("\u{e612}"),
            "md" | "mdx" => Some("\u{f48a}"),
            "json" | "toml" | "yaml" | "yml" => Some("\u{e60b}"),
            "ini" => Some("\u{e615}"),
            "sh" => Some("\u{f489}"),
            "rs" => Some("\u{e68b}"),
            "png" | "jpg" | "jpeg" | "gif" | "svg" | "webp" | "ico" => Some("\u{f02e9}"),
            "mp3" | "wav" | "flac" | "ogg" => Some("\u{f04c3}"),
            "mp4" | "mkv" | "avi" | "mov" | "webm" | "flv" => Some("\u{f0567}"),
            _ => None,
        };
        if let Some(s) = by_ext {
            return Some(s);
        }
    }
    match node_type {
        NodeType::Dir => Some("\u{f07b}"),
        NodeType::Symlink => Some("\u{f0339}"),
        NodeType::Fifo => Some("\u{f07e5}"),
        NodeType::Socket => Some("\u{f07e8}"),
        NodeType::BlockDevice | NodeType::CharDevice => Some("\u{f1dd}"),
        NodeType::File => None,
    }
}

// ---------- symlink hops ----------

#[derive(Clone, Copy, PartialEq, Eq)]
enum HopStatus {
    Ok,
    Broken,
    Loop,
}

struct Hop {
    text: String,
    status: HopStatus,
    resolved_is_dir: bool,
}

fn symlink_hops(node: &Node) -> Vec<Hop> {
    let mut hops = Vec::new();
    let mut current = node.path.clone();
    loop {
        let target = match fs::read_link(&current) {
            Ok(t) => t,
            Err(_) => break,
        };
        let text = target.to_string_lossy().into_owned();
        let target_path = if target.is_absolute() {
            target.clone()
        } else {
            match current.parent() {
                Some(p) => p.join(&target),
                None => target.clone(),
            }
        };
        let (status, is_dir) = match fs::metadata(&target_path) {
            Ok(md) => (HopStatus::Ok, md.is_dir()),
            Err(e) => {
                if e.raw_os_error() == Some(libc::ELOOP) {
                    (HopStatus::Loop, false)
                } else {
                    (HopStatus::Broken, false)
                }
            }
        };
        hops.push(Hop {
            text,
            status,
            resolved_is_dir: is_dir,
        });
        if status != HopStatus::Ok {
            break;
        }
        match fs::symlink_metadata(&target_path) {
            Ok(md) if md.file_type().is_symlink() => {
                current = target_path;
            }
            _ => break,
        }
    }
    hops
}

// ---------- rendering ----------

struct Renderer<'a> {
    opts: &'a Opts,
}

impl<'a> Renderer<'a> {
    fn render(&self, segs: &[Seg]) -> String {
        if !self.opts.color {
            return segs_text(segs);
        }
        let mut out = String::new();
        for s in segs {
            if s.codes.is_empty() || s.text.is_empty() {
                out.push_str(&s.text);
            } else {
                let codes: Vec<String> = s.codes.iter().map(|c| c.to_string()).collect();
                out.push_str(&format!("\x1b[{}m{}\x1b[0m", codes.join(";"), s.text));
            }
        }
        out
    }

    fn imp_style(&self, node: &Node) -> ImpStyle {
        let d = node.imp_diff(self.opts.imp);
        match d {
            1 => ImpStyle::Normal,
            2 => ImpStyle::Italic,
            _ if d >= 3 || d == i8::MIN => ImpStyle::Underline,
            _ => ImpStyle::Dim,
        }
    }

    fn name_segs(&self, node: &Node, is_child: bool, include_targets: bool) -> Vec<Seg> {
        let mut out: Vec<Seg> = Vec::new();
        let style = self.imp_style(node);
        let is_dir = node.node_type == NodeType::Dir;
        if is_child {
            let spaces = if self.opts.align { 3 } else { 2 };
            out.push(plain_seg(format!("{}└─ ", " ".repeat(spaces))));
        }
        if self.opts.icon {
            let icon_text = match node.icon() {
                Some(i) => format!("{} ", i),
                None => "  ".to_string(),
            };
            let mut codes: Vec<u8> = Vec::new();
            if style == ImpStyle::Dim {
                codes.push(2);
                if is_dir {
                    codes.push(34);
                }
            } else if is_dir {
                codes.push(34);
            }
            out.push(seg(icon_text, &codes));
        }
        if !node.explicit && self.opts.align && !node.display_name.starts_with('.') {
            out.push(plain_seg(" "));
        }
        // Name pieces
        let name_codes: Vec<u8> = {
            let mut v: Vec<u8> = Vec::new();
            match style {
                ImpStyle::Dim => v.push(2),
                ImpStyle::Normal => {}
                ImpStyle::Italic => v.push(3),
                ImpStyle::Underline => v.push(4),
            }
            if is_dir {
                v.push(34);
            }
            v
        };
        if !node.explicit && node.display_name.starts_with('.') {
            out.push(seg(".", &[2]));
            let rest = &node.display_name[1..];
            if !rest.is_empty() {
                out.push(seg(rest.to_string(), &name_codes));
            }
        } else {
            out.push(seg(node.display_name.clone(), &name_codes));
        }
        if self.opts.suffix {
            let suffix = node.node_type.suffix();
            if !suffix.is_empty() {
                let mut codes: Vec<u8> = vec![2];
                match style {
                    ImpStyle::Italic => codes.push(3),
                    ImpStyle::Underline => codes.push(4),
                    _ => {}
                }
                if is_dir {
                    codes.push(34);
                }
                out.push(seg(suffix.to_string(), &codes));
            }
        }
        if include_targets && self.opts.sym && node.node_type == NodeType::Symlink {
            for hop in symlink_hops(node) {
                out.push(plain_seg(" "));
                match hop.status {
                    HopStatus::Ok => {
                        out.push(seg("\u{f0054}", &[35]));
                        out.push(plain_seg(" "));
                        let codes: &[u8] = if hop.resolved_is_dir { &[34] } else { &[] };
                        out.push(seg(hop.text.clone(), codes));
                    }
                    HopStatus::Broken => {
                        out.push(seg("\u{f17a3} ", &[31]));
                        out.push(seg(hop.text.clone(), &[9, 31]));
                    }
                    HopStatus::Loop => {
                        out.push(seg("\u{f0459} ", &[33]));
                        out.push(seg(hop.text.clone(), &[33]));
                    }
                }
            }
        }
        out
    }

    fn render_name(&self, node: &Node, is_child: bool, include_targets: bool) -> String {
        let segs = self.name_segs(node, is_child, include_targets);
        self.render(&segs)
    }
}

// ---------- details ----------

fn perm_string(mode: u32) -> String {
    let perms = mode & 0o7777;
    let mut out = String::new();
    // owner, group, other
    let triples = [
        (perms >> 6 & 7, perms & 0o4000 != 0, 's', 'S'),
        (perms >> 3 & 7, perms & 0o2000 != 0, 's', 'S'),
        (perms & 7, perms & 0o1000 != 0, 't', 'T'),
    ];
    for (i, (bits, special, low, up)) in triples.iter().enumerate() {
        if i > 0 {
            out.push(' ');
        }
        out.push(if bits & 4 != 0 { 'r' } else { '-' });
        out.push(if bits & 2 != 0 { 'w' } else { '-' });
        let has_x = bits & 1 != 0;
        if *special {
            out.push(if has_x { *low } else { *up });
        } else {
            out.push(if has_x { 'x' } else { '-' });
        }
    }
    out
}

fn format_time_key(key: (i64, u32)) -> (String, String) {
    let dt_utc = DateTime::from_timestamp(key.0, key.1).unwrap_or(DateTime::UNIX_EPOCH);
    let dt: DateTime<Local> = dt_utc.with_timezone(&Local);
    (
        dt.format("%Y-%b-%d").to_string(),
        dt.format("%I:%M%P").to_string(),
    )
}

fn format_size(size: u64, unit: UnitKind) -> (String, String) {
    match unit {
        UnitKind::None => (size.to_string(), "B".to_string()),
        UnitKind::Binary | UnitKind::Decimal => {
            let (base, units): (f64, &[&str]) = if unit == UnitKind::Binary {
                (
                    1024.0,
                    &["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"],
                )
            } else {
                (1000.0, &["B", "kB", "MB", "GB", "TB", "PB", "EB"])
            };
            let mut value = size as f64;
            let mut idx = 0usize;
            while value >= base && idx < 6 {
                value /= base;
                idx += 1;
            }
            (format!("{:.1}", value), units[idx].to_string())
        }
    }
}

fn unit_fixed_width(unit: UnitKind) -> usize {
    match unit {
        UnitKind::Binary => 3,
        UnitKind::Decimal => 2,
        UnitKind::None => 1,
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Align {
    Left,
    Right,
}

struct Column {
    det: Option<Det>,
    header: &'static str,
    align: Align,
}

fn columns_for(details: &[Det]) -> Vec<Column> {
    let mut cols: Vec<Column> = details
        .iter()
        .map(|d| {
            let (header, align) = match d {
                Det::Dev => ("Device", Align::Right),
                Det::Ino => ("inode", Align::Right),
                Det::Nlink => ("Link#", Align::Right),
                Det::Typ => ("T", Align::Left),
                Det::Perm => ("Permissions", Align::Left),
                Det::Oct => ("SUGO", Align::Right),
                Det::User => ("User", Align::Left),
                Det::Uid => ("UID", Align::Right),
                Det::Group => ("Group", Align::Left),
                Det::Gid => ("GID", Align::Right),
                Det::Size => ("Size", Align::Right),
                Det::Blocks => ("Blocks", Align::Right),
                Det::Btime => ("Created", Align::Left),
                Det::Ctime => ("Changed", Align::Left),
                Det::Mtime => ("Modified", Align::Left),
                Det::Atime => ("Accessed", Align::Left),
                Det::Git => ("Git", Align::Left),
            };
            Column {
                det: Some(*d),
                header,
                align,
            }
        })
        .collect();
    cols.push(Column {
        det: None,
        header: "Name",
        align: Align::Left,
    });
    cols
}

struct FlatNode<'a> {
    node: &'a Node,
    is_child: bool,
}

impl<'a> Renderer<'a> {
    fn cell_segs(&self, det: Det, node: &Node) -> Vec<Seg> {
        let md = &node.metadata;
        match det {
            Det::Dev => vec![plain_seg(md.dev().to_string())],
            Det::Ino => vec![plain_seg(md.ino().to_string())],
            Det::Nlink => vec![plain_seg(md.nlink().to_string())],
            Det::Typ => {
                let c = node.node_type.type_char();
                let codes: &[u8] = match c {
                    'd' => &[34],
                    'f' => &[2],
                    _ => &[],
                };
                vec![seg(c.to_string(), codes)]
            }
            Det::Perm => {
                let p = perm_string(md.mode());
                let mut segs = Vec::new();
                for ch in p.chars() {
                    if ch == ' ' {
                        segs.push(plain_seg(" "));
                    } else {
                        let codes: &[u8] = match ch {
                            'r' => &[33],
                            'w' => &[31],
                            'x' => &[32],
                            '-' => &[2],
                            's' | 'S' | 't' | 'T' => &[35],
                            _ => &[],
                        };
                        segs.push(seg(ch.to_string(), codes));
                    }
                }
                segs
            }
            Det::Oct => {
                let s = format!("{:03o}", md.mode() & 0o7777);
                let len = s.chars().count();
                let mut segs = Vec::new();
                for (i, ch) in s.chars().enumerate() {
                    let from_right = len - 1 - i;
                    let codes: &[u8] = match from_right {
                        3 => &[35],
                        2 => &[34],
                        1 => &[2, 34],
                        _ => &[2],
                    };
                    segs.push(seg(ch.to_string(), codes));
                }
                segs
            }
            Det::User => {
                let text = node.user.clone().unwrap_or_default();
                let codes: &[u8] = if md.uid() == self.opts.cur_uid {
                    &[1, 34]
                } else {
                    &[2]
                };
                if text.is_empty() {
                    vec![plain_seg("")]
                } else {
                    vec![seg(text, codes)]
                }
            }
            Det::Uid => {
                let codes: &[u8] = if md.uid() == self.opts.cur_uid {
                    &[1, 34]
                } else {
                    &[2]
                };
                vec![seg(md.uid().to_string(), codes)]
            }
            Det::Group => {
                let text = node.group.clone().unwrap_or_default();
                if text.is_empty() {
                    vec![plain_seg("")]
                } else {
                    vec![seg(text, &[2])]
                }
            }
            Det::Gid => vec![seg(md.gid().to_string(), &[2])],
            Det::Blocks => vec![plain_seg(match node.blocks_value() {
                Some(v) => v.to_string(),
                None => String::new(),
            })],
            Det::Btime | Det::Ctime | Det::Mtime | Det::Atime => {
                let key = match det {
                    Det::Btime => node.btime_key(),
                    Det::Ctime => node.ctime_key(),
                    Det::Mtime => node.mtime_key(),
                    _ => node.atime_key(),
                };
                match key {
                    Some(k) => {
                        let (date, time) = format_time_key(k);
                        let codes: &[u8] = match det {
                            Det::Btime => &[1, 32],
                            Det::Ctime | Det::Mtime => &[1, 33],
                            _ => &[1, 34],
                        };
                        vec![seg(date, codes), plain_seg(format!(" {}", time))]
                    }
                    None => vec![plain_seg("")],
                }
            }
            Det::Git => vec![plain_seg("")],
            Det::Size => vec![plain_seg("")], // handled specially
        }
    }

    fn render_table(&self, rows: &[FlatNode]) -> String {
        let cols = columns_for(&self.opts.details);
        // size sub-widths
        let mut num_width = 0usize;
        for r in rows {
            if let Some(v) = r.node.size_value() {
                let (num, _) = format_size(v, self.opts.unit);
                num_width = num_width.max(num.len());
            }
        }
        let unit_w = unit_fixed_width(self.opts.unit);

        // compute widths
        let mut widths: Vec<usize> = Vec::new();
        for col in &cols {
            let mut w = if self.opts.header {
                col.header.len()
            } else {
                0
            };
            if let Some(det) = col.det {
                for r in rows {
                    let cw = if det == Det::Size {
                        match r.node.size_value() {
                            Some(_) => num_width + 1 + unit_w,
                            None => 0,
                        }
                    } else {
                        segs_width(&self.cell_segs(det, r.node))
                    };
                    w = w.max(cw);
                }
            }
            widths.push(w);
        }

        let mut out = String::new();
        // header
        if self.opts.header {
            let mut header_segs: Vec<Seg> = Vec::new();
            for (i, col) in cols.iter().enumerate() {
                let is_last = i == cols.len() - 1;
                let padded = if is_last {
                    col.header.to_string()
                } else if col.align == Align::Right {
                    format!("{:>width$}", col.header, width = widths[i])
                } else {
                    format!("{:<width$}", col.header, width = widths[i])
                };
                let text = if is_last {
                    padded
                } else {
                    format!("{} ", padded)
                };
                if self.opts.color {
                    header_segs.push(seg(text, &[1, 4, 3]));
                } else {
                    header_segs.push(plain_seg(text));
                }
            }
            out.push_str(&self.render(&header_segs));
            out.push('\n');
        }
        // rows
        for r in rows {
            let mut line_segs: Vec<Seg> = Vec::new();
            for (i, col) in cols.iter().enumerate() {
                let is_last = i == cols.len() - 1;
                if is_last {
                    // Name
                    let ns = self.name_segs(r.node, r.is_child, true);
                    line_segs.extend(ns);
                } else if let Some(det) = col.det {
                    if det == Det::Size {
                        match r.node.size_value() {
                            None => {
                                line_segs.push(plain_seg(" ".repeat(widths[i])));
                            }
                            Some(v) => {
                                let (num, unit) = format_size(v, self.opts.unit);
                                let num_field = widths[i].saturating_sub(1 + unit_w);
                                let num_pad = num_field.saturating_sub(num.len());
                                line_segs.push(plain_seg(" ".repeat(num_pad)));
                                if self.opts.color {
                                    line_segs.push(seg(num, &[1]));
                                } else {
                                    line_segs.push(plain_seg(num));
                                }
                                line_segs.push(plain_seg(" "));
                                // unit right-aligned in unit_w
                                let unit_pad = unit_w.saturating_sub(unit.len());
                                if unit_pad > 0 {
                                    line_segs.push(plain_seg(" ".repeat(unit_pad)));
                                }
                                if unit.len() > 1 {
                                    line_segs.push(plain_seg(unit[..unit.len() - 1].to_string()));
                                }
                                let last_char = unit[unit.len() - 1..].to_string();
                                if self.opts.color {
                                    line_segs.push(seg(last_char, &[2]));
                                } else {
                                    line_segs.push(plain_seg(last_char));
                                }
                            }
                        }
                    } else {
                        let cs = self.cell_segs(det, r.node);
                        let cw = segs_width(&cs);
                        let pad = widths[i].saturating_sub(cw);
                        if col.align == Align::Right {
                            if pad > 0 {
                                line_segs.push(plain_seg(" ".repeat(pad)));
                            }
                            line_segs.extend(cs);
                        } else {
                            line_segs.extend(cs);
                            if pad > 0 {
                                line_segs.push(plain_seg(" ".repeat(pad)));
                            }
                        }
                    }
                    line_segs.push(plain_seg(" "));
                }
            }
            out.push_str(&self.render(&line_segs));
            out.push('\n');
        }
        out
    }

    fn render_list(&self, rows: &[FlatNode]) -> String {
        let mut out = String::new();
        for r in rows {
            out.push_str(&self.render_name(r.node, r.is_child, true));
            out.push('\n');
        }
        out
    }

    fn render_grid(&self, nodes: &[Node]) -> String {
        if nodes.is_empty() {
            return String::new();
        }
        // cells
        let cells: Vec<Vec<Seg>> = nodes
            .iter()
            .map(|n| self.name_segs(n, false, false))
            .collect();
        let plain_widths: Vec<usize> = cells.iter().map(|c| segs_width(c)).collect();
        let max_w = *plain_widths.iter().max().unwrap_or(&0);
        let width = match grid_term_width() {
            Some(w) if w > 0 => w,
            _ => {
                // single column without padding
                let mut out = String::new();
                for c in &cells {
                    out.push_str(&self.render(c));
                    out.push('\n');
                }
                return out;
            }
        };
        let n = nodes.len();
        let mut chosen: Option<(usize, usize)> = None; // (rows, cols)
        for rows in 1..=n {
            let cols = (n + rows - 1) / rows;
            let total = cols * max_w + cols.saturating_sub(1) * 2;
            if total <= width {
                chosen = Some((rows, cols));
                break;
            }
        }
        let (rows, cols) = match chosen {
            Some(v) => v,
            None => {
                let mut out = String::new();
                for c in &cells {
                    out.push_str(&self.render(c));
                    out.push('\n');
                }
                return out;
            }
        };
        if cols == 1 {
            // fall back to unpadded single column (as observed for very narrow terminals)
            // Determine whether this is a forced-narrow case or actually chosen:
            // When cols==1 we output unpadded cells.
            let mut out = String::new();
            for c in &cells {
                out.push_str(&self.render(c));
                out.push('\n');
            }
            return out;
        }
        let mut out = String::new();
        for row in 0..rows {
            let mut line = String::new();
            let mut first = true;
            for col in 0..cols {
                let idx = if self.opts.down {
                    col * rows + row
                } else {
                    row * cols + col
                };
                if idx >= n {
                    continue;
                }
                if !first {
                    line.push_str("  ");
                }
                first = false;
                line.push_str(&self.render(&cells[idx]));
                let pad = max_w - plain_widths[idx];
                line.push_str(&" ".repeat(pad));
            }
            out.push_str(&line);
            out.push('\n');
        }
        out
    }

    fn render_listing(&self, nodes: &[Node], explicit: bool) -> String {
        if !self.opts.details.is_empty() {
            let flat = flatten_nodes(nodes, explicit, self.opts.collapse);
            self.render_table(&flat)
        } else if self.opts.grid {
            // grid ignores collapse and (for dir nodes) explicit distinction aside from names
            self.render_grid(nodes)
        } else {
            let flat = flatten_nodes(nodes, explicit, self.opts.collapse);
            self.render_list(&flat)
        }
    }
}

fn flatten_nodes<'a>(nodes: &'a [Node], explicit: bool, collapse: bool) -> Vec<FlatNode<'a>> {
    if explicit || !collapse {
        return nodes
            .iter()
            .map(|n| FlatNode {
                node: n,
                is_child: false,
            })
            .collect();
    }
    // dependency map: child name -> principal name
    let deps: HashMap<&str, &str> = HashMap::from([("Cargo.lock", "Cargo.toml")]);
    let names: HashSet<&str> = nodes.iter().map(|n| n.base_name.as_str()).collect();
    let mut children_of: HashMap<&str, Vec<&Node>> = HashMap::new();
    let mut child_ptrs: HashSet<*const Node> = HashSet::new();
    for n in nodes {
        if let Some(principal) = deps.get(n.base_name.as_str()) {
            if names.contains(principal) {
                children_of
                    .entry(*principal)
                    .or_default()
                    .push(n);
                child_ptrs.insert(n as *const Node);
            }
        }
    }
    if child_ptrs.is_empty() {
        return nodes
            .iter()
            .map(|n| FlatNode {
                node: n,
                is_child: false,
            })
            .collect();
    }
    let mut out: Vec<FlatNode> = Vec::new();
    for n in nodes {
        if child_ptrs.contains(&(n as *const Node)) {
            continue;
        }
        out.push(FlatNode {
            node: n,
            is_child: false,
        });
        if let Some(children) = children_of.get(n.base_name.as_str()) {
            for c in children {
                out.push(FlatNode {
                    node: c,
                    is_child: true,
                });
            }
        }
    }
    out
}

// ---------- args processing ----------

fn process_details(values: &[String]) -> Vec<Det> {
    fn insert(list: &mut Vec<Det>, d: Det) {
        if let Some(pos) = list.iter().position(|x| *x == d) {
            list.remove(pos);
        }
        list.push(d);
    }
    let mut out: Vec<Det> = Vec::new();
    for v in values {
        match v.as_str() {
            "none" => out.clear(),
            "std" => {
                for d in [
                    Det::Nlink,
                    Det::Typ,
                    Det::Perm,
                    Det::User,
                    Det::Group,
                    Det::Size,
                    Det::Mtime,
                ] {
                    insert(&mut out, d);
                }
            }
            "all" => {
                for d in [
                    Det::Dev,
                    Det::Ino,
                    Det::Nlink,
                    Det::Typ,
                    Det::Perm,
                    Det::Oct,
                    Det::User,
                    Det::Uid,
                    Det::Group,
                    Det::Gid,
                    Det::Size,
                    Det::Blocks,
                    Det::Btime,
                    Det::Ctime,
                    Det::Mtime,
                    Det::Atime,
                    Det::Git,
                ] {
                    insert(&mut out, d);
                }
            }
            "dev" => insert(&mut out, Det::Dev),
            "ino" => insert(&mut out, Det::Ino),
            "nlink" => insert(&mut out, Det::Nlink),
            "typ" => insert(&mut out, Det::Typ),
            "perm" => insert(&mut out, Det::Perm),
            "oct" => insert(&mut out, Det::Oct),
            "user" => insert(&mut out, Det::User),
            "uid" => insert(&mut out, Det::Uid),
            "group" => insert(&mut out, Det::Group),
            "gid" => insert(&mut out, Det::Gid),
            "size" => insert(&mut out, Det::Size),
            "blocks" => insert(&mut out, Det::Blocks),
            "btime" => insert(&mut out, Det::Btime),
            "ctime" => insert(&mut out, Det::Ctime),
            "mtime" => insert(&mut out, Det::Mtime),
            "atime" => insert(&mut out, Det::Atime),
            "git" => insert(&mut out, Det::Git),
            _ => {}
        }
    }
    out
}

fn process_types(values: &[String]) -> HashSet<TypeFilter> {
    let mut out: HashSet<TypeFilter> = HashSet::new();
    let all = [
        TypeFilter::Dir,
        TypeFilter::Symlink,
        TypeFilter::Fifo,
        TypeFilter::Socket,
        TypeFilter::BlockDevice,
        TypeFilter::CharDevice,
        TypeFilter::File,
    ];
    for v in values {
        match v.as_str() {
            "none" => out.clear(),
            "all" => {
                for t in all {
                    out.insert(t);
                }
            }
            "dir" => {
                out.insert(TypeFilter::Dir);
            }
            "symlink" => {
                out.insert(TypeFilter::Symlink);
            }
            "fifo" => {
                out.insert(TypeFilter::Fifo);
            }
            "socket" => {
                out.insert(TypeFilter::Socket);
            }
            "block-device" => {
                out.insert(TypeFilter::BlockDevice);
            }
            "char-device" => {
                out.insert(TypeFilter::CharDevice);
            }
            "file" => {
                out.insert(TypeFilter::File);
            }
            _ => {}
        }
    }
    out
}

fn process_sorts(values: &[String]) -> Vec<SortField> {
    let mut out: Vec<SortField> = Vec::new();
    for v in values {
        let field = match v.as_str() {
            "none" => {
                out.clear();
                continue;
            }
            "dev" => SortField::Dev,
            "ino" => SortField::Ino,
            "nlink" => SortField::Nlink,
            "typ" => SortField::Typ,
            "cat" => SortField::Cat,
            "user" => SortField::User,
            "uid" => SortField::Uid,
            "group" => SortField::Group,
            "gid" => SortField::Gid,
            "size" => SortField::Size,
            "blocks" => SortField::Blocks,
            "btime" => SortField::Btime,
            "ctime" => SortField::Ctime,
            "mtime" => SortField::Mtime,
            "atime" => SortField::Atime,
            "name" => SortField::Name,
            "cname" => SortField::Cname,
            "ext" => SortField::Ext,
            "inode_" => SortField::InoRev,
            "nlinks_" => SortField::NlinkRev,
            "typ_" => SortField::TypRev,
            "cat_" => SortField::CatRev,
            "user_" => SortField::UserRev,
            "uid_" => SortField::UidRev,
            "group_" => SortField::GroupRev,
            "gid_" => SortField::GidRev,
            "size_" => SortField::SizeRev,
            "blocks_" => SortField::BlocksRev,
            "btime_" => SortField::BtimeRev,
            "ctime_" => SortField::CtimeRev,
            "mtime_" => SortField::MtimeRev,
            "atime_" => SortField::AtimeRev,
            "name_" => SortField::NameRev,
            "cname_" => SortField::CnameRev,
            "ext_" => SortField::ExtRev,
