        };
        if !out.contains(&field) {
            out.push(field);
        }
    }
    out
}

fn get_strings(matches: &clap::ArgMatches, id: &str) -> Vec<String> {
    matches
        .get_many::<String>(id)
        .map(|v| v.cloned().collect())
        .unwrap_or_default()
}

fn visible_importance(node: &Node, cutoff: i8) -> bool {
    let d = node.imp_diff(cutoff);
    d >= 0 || d == i8::MIN
}

fn main() {
    let matches = build_command().get_matches();

    let paths: Vec<PathBuf> = matches
        .get_many::<PathBuf>("paths")
        .map(|v| v.cloned().collect())
        .unwrap_or_else(|| vec![PathBuf::from(".")]);

    let det_values = get_strings(&matches, "det");
    let typ_values = get_strings(&matches, "typ");
    let sort_values = get_strings(&matches, "sort");

    let opts = Opts {
        details: process_details(&det_values),
        header: *matches.get_one::<bool>("header").unwrap_or(&true),
        unit: match matches.get_one::<String>("unit").map(|s| s.as_str()) {
            Some("decimal") => UnitKind::Decimal,
            Some("none") => UnitKind::None,
            _ => UnitKind::Binary,
        },
        grid: *matches.get_one::<bool>("grid").unwrap_or(&false),
        down: *matches.get_one::<bool>("down").unwrap_or(&false),
        icon: *matches.get_one::<bool>("icon").unwrap_or(&true),
        suffix: *matches.get_one::<bool>("suffix").unwrap_or(&true),
        sym: *matches.get_one::<bool>("sym").unwrap_or(&true),
        collapse: *matches.get_one::<bool>("collapse").unwrap_or(&true),
        align: *matches.get_one::<bool>("align").unwrap_or(&true),
        types: process_types(&typ_values),
        imp: *matches.get_one::<i8>("imp").unwrap_or(&0),
        exclude: matches.get_one::<Regex>("exclude").cloned(),
        only: matches.get_one::<Regex>("only").cloned(),
        sorts: process_sorts(&sort_values),
        color: color_enabled(),
        cur_uid: unsafe { libc::getuid() },
    };

    let renderer = Renderer { opts: &opts };

    // Partition input paths.
    let mut errors: Vec<(PathBuf, std::io::Error)> = Vec::new();
    let mut files: Vec<Node> = Vec::new();
    let mut dirs: Vec<PathBuf> = Vec::new();
    for path in &paths {
        match fs::symlink_metadata(path) {
            Err(e) => errors.push((path.clone(), e)),
            Ok(md) => {
                if md.is_dir() {
                    dirs.push(path.clone());
                } else {
                    files.push(Node::new(
                        path.clone(),
                        path.display().to_string(),
                        true,
                        md,
                    ));
                }
            }
        }
    }

    let total = paths.len();

    // Error sections first.
    for (path, err) in &errors {
        if opts.color {
            println!(
                "\x1b[1m{}\x1b[0m:\n\t\x1b[1;31merror:\x1b[0m {}",
                path.display(),
                err
            );
        } else {
            println!("{}:\n\terror: {}", path.display(), err);
        }
    }

    // File group.
    if !files.is_empty() {
        let out = renderer.render_listing(&files, true);
        print!("{}", out);
    }

    // Dir sections.
    for dir_path in &dirs {
        if total > 1 {
            if opts.color {
                print!("\n\x1b[1m{}:\x1b[0m\n", dir_path.display());
            } else {
                print!("\n{}:\n", dir_path.display());
            }
        }
        match read_dir_nodes(dir_path, &opts) {
            Err(e) => {
                if opts.color {
                    println!("\x1b[1;31merror:\x1b[0m {}", e);
                } else {
                    println!("error: {}", e);
                }
            }
            Ok(nodes) => {
                let out = renderer.render_listing(&nodes, false);
                print!("{}", out);
            }
        }
    }
}

fn read_dir_nodes(dir_path: &Path, opts: &Opts) -> Result<Vec<Node>, std::io::Error> {
    let reader = fs::read_dir(dir_path)?;
    let mut nodes: Vec<Node> = Vec::new();
    for entry in reader {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let md = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };
        let display = entry.file_name().to_string_lossy().into_owned();
        let node = Node::new(entry.path(), display, false, md);
        // Filtering
        if !opts.types.contains(&node.node_type.filter()) {
            continue;
        }
        if let Some(only) = &opts.only {
            if !only.is_match(&node.base_name) {
                continue;
            }
        }
        if let Some(exclude) = &opts.exclude {
            if exclude.is_match(&node.base_name) {
                continue;
            }
        }
        if !visible_importance(&node, opts.imp) {
            continue;
        }
        nodes.push(node);
    }
    // Sorting (stable). Evaluate every field for each comparison (as in the original).
    let sorts = &opts.sorts;
    nodes.sort_by(|a, b| {
        let mut result = Ordering::Equal;
        for f in sorts {
            let c = f.cmp(a, b);
            if result == Ordering::Equal {
                result = c;
            }
        }
        result
    });
    Ok(nodes)
}

// Keep OsStr bytes import used on all builds (for potential future use).
#[allow(dead_code)]
fn _os_bytes(s: &OsString) -> usize {
    s.as_bytes().len()
}
