//! A minimal terminal-size helper for Unix-like systems.
//!
//! It reports the current terminal dimensions using the `TIOCGWINSZ`
//! ioctl on the standard streams.

/// Terminal width in characters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

/// Terminal height in characters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

fn size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the controlling terminal, if one is available.
///
/// The standard output, standard error and standard input streams are
/// probed in that order.
