import tempfile, os
def grid(names, cols, down="true"):
    d=tempfile.mkdtemp()
    for n in names: open(os.path.join(d,n),"w").close()
    out=run_pty2([d,"-i=false","-S=false","-g=true",f"-D={down}","-s=cname","-I=-1"], cols=cols, env_extra={"NO_COLOR":"1"})
    return [l.split() for l in out.replace("\r\n","\n").splitlines()]

for n,cols in [(18,40),(19,50),(20,50),(21,50),(22,50),(25,60),(14,30),(15,30),(16,30),(26,40),(12,20)]:
    names=[f"n{i:02d}" for i in range(n)]
    rows=grid(names,cols)
    print(f"n={n} cols={cols} rows={len(rows)} cols_first={len(rows[0]) if rows else 0}")
    for r in rows: print(" ",r)
