        .long_about("\\u{1b}[1;31mpls\\u{1b}[0m is a prettier and powerful ls(1) for the pros.\\n\\n\\u{1b}[1mRead docs:\\u{1b}[0m \\u{1b}]8;;https://pls.cli.rs/\\u{1b}\\\\https://pls.cli.rs/\\u{1b}]8;;\\u{1b}\\\\\\n\\u{1b}[1mGet source:\\u{1b}[0m \\u{1b}]8;;https://github.com/pls-rs/pls/\\u{1b}\\\\https://github.com/pls-rs/pls/\\u{1b}]8;;\\u{1b}\\\\\\n\\u{1b}[1mSponsor:\\u{1b}[0m \\u{1b}]8;;https://github.com/sponsors/dhruvkb/\\u{1b}\\\\https://github.com/sponsors/dhruvkb/\\u{1b}]8;;\\u{1b}\\\\")'''
assert old_about in s, "about not found"
s=s.replace(old_about,new_about)

# Grid down permutation
old_grid='''        let mut out = String::new();
        for row in 0..rows {
            let mut line = String::new();
            let mut first = true;
            for col in 0..cols {
                let idx = if self.opts.down {
                    col * rows + row
                } else {
                    row * cols + col
                };
                if idx >= n {
                    continue;
                }
                if !first {
                    line.push_str("  ");
                }
                first = false;
                line.push_str(&self.render(&cells[idx]));
                let pad = max_w - plain_widths[idx];
                line.push_str(&" ".repeat(pad));
            }
            out.push_str(&line);
            out.push('\\n');
        }
        out'''
new_grid='''        // In column-first mode the original display walks the cells in
        // "transposed" order and then chunks that sequence into rows; this
        // matters when the final column is incomplete.
        let order: Vec<usize> = if self.opts.down {
            let mut v: Vec<usize> = Vec::with_capacity(n);
            for r in 0..rows {
                let mut idx = r;
                while idx < n {
                    v.push(idx);
                    idx += rows;
                }
            }
            v
        } else {
            (0..n).collect()
        };
        let mut out = String::new();
        for chunk in order.chunks(cols) {
            let mut line = String::new();
            for (i, &idx) in chunk.iter().enumerate() {
                if i > 0 {
                    line.push_str("  ");
                }
                line.push_str(&self.render(&cells[idx]));
                let pad = max_w - plain_widths[idx];
                line.push_str(&" ".repeat(pad));
            }
            out.push_str(&line);
            out.push('\\n');
        }
        out'''
assert old_grid in s, "grid not found"
s=s.replace(old_grid,new_grid)
open('src/main.rs','w').write(s)
